#define main probe_main
#include "diagnose_sparse_write4.cpp"
#undef main
#include <fstream>
Seq grammar(Seq s,std::mt19937&r,int mode){std::vector<int>out;for(size_t t=0;t<s.tokens.size();t+=3){int object=s.tokens[t],owner=s.tokens[t+1];bool reverse=mode==1||(mode==0&&r()%2);if(mode==2)out.insert(out.end(),{object,12,owner,12});else if(reverse)out.insert(out.end(),{owner,object,12});else out.insert(out.end(),{object,owner,12});}s.tokens=out;return s;}
#include "token_write_hard4.hpp"
#include <chrono>
int main(){try{for(unsigned seed:{42u,123u,2026u,7u,999u}){Net net(seed);std::ifstream f("build/init_write4_2_adam_"+std::to_string(seed)+".weights",std::ios::binary);if(!f.read((char*)net.w.data(),sizeof(net.w))||f.peek()!=EOF)throw std::runtime_error("weights");tao::TokenWriteHard4 hard(net.w);for(int syntax:{0,1,2}){std::mt19937 rng(518239+syntax);int correct=0,parity=0;for(int i=0;i<128;++i){auto s=grammar(make(rng,512),rng,syntax);int ref;net.run(s,nullptr,nullptr,&ref);hard.reset();for(int t:s.tokens)hard.step(s.query,t);parity+=hard.memory==ref;correct+=hard.memory==s.target;}if(parity!=128)throw std::runtime_error("hard parity");printf("seed=%u syntax=%d noise512 n128 hardacc=%.6f parity=%d\n",seed,syntax,correct/128.,parity);}std::mt19937 rng(77);auto sample=grammar(make(rng,32),rng,0);volatile int sink=0;double times[7];for(int r=0;r<7;++r){auto start=std::chrono::steady_clock::now();for(int n=0;n<400;++n){hard.reset();for(int t:sample.tokens)sink+=hard.step(sample.query,t);}times[r]=std::chrono::duration<double,std::micro>(std::chrono::steady_clock::now()-start).count()/(400*sample.tokens.size());}std::sort(times,times+7);printf("seed=%u hard_us_token=%.6f sink=%d\n",seed,times[3],int(sink));}return 0;}catch(const std::exception&e){printf("FAIL %s\n",e.what());return 1;}}
